export const ServerNotification__Thread = Schema.Struct({
    agentNickname: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Optional random unique nickname assigned to an AgentControl-spawned sub-agent.",
        }),
        Schema.Null,
    ])),
    agentRole: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Optional role (agent_role) assigned to an AgentControl-spawned sub-agent.",
        }),
        Schema.Null,
    ])),
    cliVersion: Schema.String.annotate({
        description: "Version of the CLI that created the thread.",
    }),
    createdAt: Schema.Number.annotate({
        description: "Unix timestamp (in seconds) when the thread was created.",
        format: "int64",
    }).check(Schema.isInt().annotate({ expected: "an integer" })),
    cwd: Schema.suspend(() => ServerNotification__AbsolutePathBuf).annotate({ description: "Working directory captured for the thread." }),
    ephemeral: Schema.Boolean.annotate({
        description: "Whether the thread is ephemeral and should not be materialized on disk.",
    }),
    forkedFromId: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Source thread id when this thread was created by forking another thread.",
        }),
        Schema.Null,
    ])),
    gitInfo: Schema.optionalKey(Schema.Union([ServerNotification__GitInfo, Schema.Null]).annotate({
        description: "Optional Git metadata captured when the thread was created.",
    })),
    historyMode: Schema.optionalKey(Schema.suspend(() => ServerNotification__ThreadHistoryMode).annotate({
        description: "Persisted thread history contract selected when this thread was created.",
        default: "legacy",
    })),
    id: Schema.String.annotate({
        description: "Identifier for this thread. Codex-generated thread IDs are UUIDv7.",
    }),
    model: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Current configured model when loaded, otherwise the latest persisted model. Null when unavailable. This is not per-turn execution telemetry.",
        }),
        Schema.Null,
    ])),
    modelProvider: Schema.String.annotate({
        description: "Model provider used for this thread (for example, 'openai').",
    }),
    name: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({ description: "Optional user-facing thread title." }),
        Schema.Null,
    ])),
    originator: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Originator recorded when the thread was created, independent of its current client or executor. Null when the recorded originator is unavailable.",
        }),
        Schema.Null,
    ])),
    parentThreadId: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "The ID of the parent thread. This will only be set if this thread is a subagent.",
        }),
        Schema.Null,
    ])),
    path: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({ description: "[UNSTABLE] Path to the thread on disk." }),
        Schema.Null,
    ])),
    preview: Schema.String.annotate({
        description: "Usually the first user message in the thread, if available.",
    }),
    projectId: Schema.Union([
        Schema.String.annotate({
            description: "Canonical project assignment owned by app-server, if any.",
        }),
        Schema.Null,
    ]),
    reasoningEffort: Schema.optionalKey(Schema.Union([ServerNotification__ReasoningEffort, Schema.Null]).annotate({
        description: "Current configured reasoning effort when loaded, otherwise the latest persisted effort. Null when unset or unavailable. This is not per-turn execution telemetry.",
    })),
    recencyAt: Schema.optionalKey(Schema.Union([
        Schema.Number.annotate({
            description: "Unix timestamp (in seconds) used for thread recency ordering.",
            format: "int64",
        }).check(Schema.isInt().annotate({ expected: "an integer" })),
        Schema.Null,
    ])),
    section: Schema.optionalKey(Schema.Union([ServerNotification__ThreadSection, Schema.Null]).annotate({
        description: "The independently persisted section selected for this thread, if any.",
    })),
    sectionEnteredAt: Schema.optionalKey(Schema.Union([
        Schema.Number.annotate({
            description: "Unix timestamp in seconds when the thread entered its current section.",
            format: "int64",
        }).check(Schema.isInt().annotate({ expected: "an integer" })),
        Schema.Null,
    ])),
    sessionId: Schema.String.annotate({
        description: "Session id shared by threads that belong to the same session tree.",
    }),
    source: Schema.suspend(() => ServerNotification__SessionSource).annotate({
        description: "Origin of the thread (CLI, VSCode, codex exec, codex app-server, etc.).",
    }),
    status: Schema.suspend(() => ServerNotification__ThreadStatus).annotate({ description: "Current runtime status for the thread." }),
    threadSource: Schema.optionalKey(Schema.Union([ServerNotification__ThreadSource, Schema.Null]).annotate({
        description: "Optional analytics source classification for this thread.",
    })),
    turns: Schema.Array(ServerNotification__Turn).annotate({
        description: "Only populated on `thread/resume`, `thread/fork`, and `thread/read` (when `includeTurns` is true) responses. For all other responses and notifications returning a Thread, the turns field will be an empty list.",
    }),
    updatedAt: Schema.Number.annotate({
        description: "Unix timestamp (in seconds) when the thread was last updated.",
        format: "int64",
    }).check(Schema.isInt().annotate({ expected: "an integer" })),
}).annotate({ identifier: "ServerNotification__Thread" });
