export const V2TurnStartParams = Schema.Struct({
    approvalPolicy: Schema.optionalKey(Schema.Union([V2TurnStartParams__AskForApproval, Schema.Null]).annotate({
        description: "Override the approval policy for this turn and subsequent turns.",
    })),
    approvalsReviewer: Schema.optionalKey(Schema.Union([V2TurnStartParams__ApprovalsReviewer, Schema.Null]).annotate({
        description: "Override where approval requests are routed for review on this turn and subsequent turns.",
    })),
    clientUserMessageId: Schema.optionalKey(Schema.Union([Schema.String, Schema.Null])),
    cwd: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Override the working directory for this turn and subsequent turns.",
        }),
        Schema.Null,
    ])),
    disabledPluginIds: Schema.optionalKey(Schema.Union([
        Schema.Array(Schema.String).annotate({
            description: "Replace this thread's disabled plugin IDs. Omitted/null preserves the list; [] clears it.",
        }),
        Schema.Null,
    ])),
    effort: Schema.optionalKey(Schema.Union([V2TurnStartParams__ReasoningEffort, Schema.Null]).annotate({
        description: "Override the reasoning effort for this turn and subsequent turns.",
    })),
    input: Schema.Array(V2TurnStartParams__UserInput),
    model: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Override the model for this turn and subsequent turns.",
        }),
        Schema.Null,
    ])),
    outputSchema: Schema.optionalKey(Schema.Json.annotate({
        expected: "JSON value",
        description: "Optional JSON Schema used to constrain the final assistant message for this turn.",
    })),
    personality: Schema.optionalKey(Schema.Union([V2TurnStartParams__Personality, Schema.Null]).annotate({
        description: "@deprecated `friendly` and `pragmatic` no longer select a style. Changing this does not rewrite the thread's existing instructions.",
    })),
    sandboxPolicy: Schema.optionalKey(Schema.Union([V2TurnStartParams__SandboxPolicy, Schema.Null]).annotate({
        description: "Override the sandbox policy for this turn and subsequent turns.",
    })),
    serviceTier: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Override the service tier for this turn and subsequent turns.",
        }),
        Schema.Null,
    ])),
    serviceTierForTurn: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Override the service tier only when this request starts a new turn. Use \"default\" for standard speed. Omitted or null inherits the thread's tier. Does not change the thread's tier or a turn being steered.",
        }),
        Schema.Null,
    ])),
    summary: Schema.optionalKey(Schema.Union([V2TurnStartParams__ReasoningSummary, Schema.Null]).annotate({
        description: "Override the reasoning summary for this turn and subsequent turns.",
    })),
    threadId: Schema.String,
    toolOutput: Schema.optionalKey(Schema.Union([V2TurnStartParams__TurnToolOutput, Schema.Null])),
    turnTrigger: Schema.optionalKey(Schema.Union([
        Schema.String.annotate({
            description: "Optional source classification for the caller that starts this turn. Ignored when this request steers an already-active turn.",
        }),
        Schema.Null,
    ])),
}).annotate({ title: "TurnStartParams" });
